export const SubscribeSubmit: Story = {
  name: 'Subscribe — two-step flow (HPC-035, not shipped)',
  // enableNameCapture is opt-in and off in production: SFCC-55 ships the placeholder path
  // below. This story keeps the modal exercised so HPC-035 inherits working, covered code.
  render: (args) => (
    <div style={{ width: '100%' }}>
      <Footer {...args} privacyPolicyHref="/privacy-policy" enableNameCapture />
    </div>
  ),
  play: async ({ canvasElement }) => {
    // Step 1 — email entry
    const canvas = within(canvasElement);
    const emailInput = canvas.getByRole('textbox', { name: /email/i });
    await userEvent.type(emailInput, 'test@example.com');
    const submitBtn = canvas.getByRole('button', { name: /subscribe/i });
    await userEvent.click(submitBtn);

    // Step 2 — modal should open. testing.md §Layer-2 requires within(canvasElement);
    // portal exception: createPortal attaches the dialog to document.body, outside the
    // Storybook canvas boundary, so within(document.body) is the required workaround.
    const doc = within(document.body);
    await expect(doc.getByRole('dialog')).toBeInTheDocument();
    await userEvent.type(doc.getByRole('textbox', { name: /first name/i }), 'Jane');
    await userEvent.type(doc.getByRole('textbox', { name: /last name/i }), 'Smith');
    await userEvent.click(doc.getByRole('button', { name: /continue/i }));

    // Modal closes. HPC-036 not yet landed → component shows the 'unavailable' message
    // rather than false success. Update this assertion to /on the list/i once the Omneo
    // POST is wired and setSubmitState('success') is reachable via a real API response.
    await expect(doc.queryByRole('dialog')).not.toBeInTheDocument();
    await expect(canvas.getByText(/temporarily unavailable/i)).toBeInTheDocument();
  },
};

export const SubscribeModalOpen: Story = {
  name: 'Subscribe — modal open state (HPC-035, not shipped)',
  render: (args) => (
    <div style={{ width: '100%' }}>
      <Footer {...args} privacyPolicyHref="/privacy-policy" enableNameCapture />
    </div>
  ),
  // Covers the dialog mechanics now owned by useZimmModal: focus entry, the Tab trap in
  // both wrap directions, the body-scroll lock, Escape dismissal and focus restore. Mutation-
  // tested — breaking the setTimeout focus, the Escape branch, the Tab branch or the overflow
  // write each fails this play. Before it existed, those mutations passed the whole Storybook
  // suite, so the hook extraction would have had no CI net at all.
  //
  // The one branch this cannot reach is the trap's `!el.hasAttribute('disabled')` filter:
  // nothing in SubscribeModal is ever disabled, so there is no disabled control here for it to
  // exclude. That one is covered with a synthetic harness in hooks/useZimmModal.test.tsx.
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);

    // Read, not assumed: the hook restores whatever inline value it found, so the release
    // assertion at the end compares against this rather than a hardcoded ''. Asserting it is
    // not ALREADY 'hidden' is what stops the lock assertion below from passing vacuously.
    const overflowBefore = document.body.style.overflow;
    await expect(overflowBefore).not.toBe('hidden');

    await userEvent.type(canvas.getByRole('textbox', { name: /email/i }), 'test@example.com');
    const trigger = canvas.getByRole('button', { name: /subscribe/i });
    await userEvent.click(trigger);

    // Portal renders outside canvasElement — testing.md §Layer-2 exception.
    const doc = within(document.body);
    const dialog = doc.getByRole('dialog');
    await expect(dialog).toBeInTheDocument();
    await expect(dialog).toHaveAttribute('aria-modal', 'true');

    // Scroll lock: the page behind a modal must not scroll out from under it.
    await expect(document.body.style.overflow).toBe('hidden');

    // Focus is moved into the dialog, onto the first field
    const firstName = doc.getByRole('textbox', { name: /first name/i });
    await expect(firstName).toHaveFocus();


=== 230,260 ===

    // S2 preconditions. The two equality checks below are pure before/after comparisons, so a
    // collapsed container satisfies them vacuously: display:none, height:0;overflow:hidden and
    // an ancestor display:none each measure 0 both times and pass. Every rect is 0 in jsdom too,
    // which would make the whole assertion unconditionally true if this play is ever driven
    // through portable stories. Anchoring both operands above zero is what makes it an assertion.
    await expect(slotBefore).toBeGreaterThan(0);
    await expect(heightBefore).toBeGreaterThan(0);

    await userEvent.type(canvas.getByRole('textbox', { name: /email/i }), 'test@example.com');
    await userEvent.click(canvas.getByRole('button', { name: /subscribe/i }));

    // No modal — the default build does not collect names (HPC-035 is a separate story with no
    // design yet). Queried against document.body because the modal would portal outside canvas.
    await expect(within(document.body).queryByRole('dialog')).not.toBeInTheDocument();

    // The shopper still gets honest feedback rather than a false success.
    await expect(canvas.getByText(/temporarily unavailable/i)).toBeInTheDocument();
    await expect(canvas.queryByText(/on the list/i)).not.toBeInTheDocument();

    // No layout shift. The field and the message are different heights (45px vs 36px of text),
    // so without subscribeControl's minHeight reservation the column re-flows — measurably at
    // every viewport, and visibly on mobile where the columns stack and the footer itself moves.
    // Asserted on the slot as well as the footer: at desktop widths the taller site-map column
    // sets the row height, so a footer-only check passes even when the column has shifted.
    // One decimal place. getBoundingClientRect reports sub-pixel jitter, so comparing raw
    // values would fail an equality check on a layout that did not actually move.
    const LAYOUT_PRECISION_DP = 1;
    const rounded = (n: number) => Number(n.toFixed(LAYOUT_PRECISION_DP));
    await expect(rounded(slot.getBoundingClientRect().height)).toBe(rounded(slotBefore));
    await expect(rounded(footer.getBoundingClientRect().height)).toBe(rounded(heightBefore));

